import { z } from 'zod';

// invalid_type_error: shown when input is not a string
const schema1 = z.string({
  invalid_type_error: "Expected a string"
});

// required_error: shown when a required value is missing  
const schema2 = z.string({
  required_error: "This field is required"
});

// Both options combined
const schema3 = z.string({
  invalid_type_error: "Must be a string",
  required_error: "String field is required"
});

// errorMap: custom function to transform validation errors
const customErrorMap: z.ZodErrorMap = (issue, ctx) => {
  if (issue.code === z.ZodIssueCode.invalid_type) {
    return { message: `Custom: expected string but got ${issue.received}` };
  }
  return { message: ctx.defaultError };
};

