import { z } from 'zod';

// In Zod 4.6.7, string() no longer accepts errorMap, invalid_type_error, required_error, description.
// Here's how to achieve the same functionality:

// For description: use .describe()
const emailSchema = z.string().describe('User email address');

// For invalid_type_error & required_error: use .refine() or .superRefine()
const nameSchema = z.string().refine(
  (val) => val.length > 0,
  { message: 'Name is required' }
);

// For custom error mapping with superRefine
const passwordSchema = z.string().superRefine((val, ctx) => {
  if (!val) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: 'Password is required'
    });
  }
  if (val.length < 8) {
    ctx.addIssue({
      code: z.ZodIssueCode.too_small,
      type: 'string',
      minimum: 8,
      inclusive: true,
      message: 'Password must be at least 8 characters'
    });
  }
});

// Test
console.log(emailSchema.safeParse('test@example.com'));
console.log(nameSchema.safeParse(''));
console.log(passwordSchema.safeParse('short'));

import { QueryClient } from '@tanstack/react-query';

const queryClient = new QueryClient();

// Define a query key and fetch function
const todoQueryKey = ['todos'];
const fetchTodos = async () => {
  const response = await fetch('https://jsonplaceholder.typicode.com/todos/1');
  if (!response.ok) throw new Error('Failed to fetch');
  return response.json();
};

// fetchQuery - immediately fetches and returns data
const todo = await queryClient.fetchQuery({
  queryKey: todoQueryKey,
  queryFn: fetchTodos,
});
console.log('Fetched:', todo);

// prefetchQuery - fetches in background, caches the data
await queryClient.prefetchQuery({
  queryKey: todoQueryKey,
  queryFn: fetchTodos,
});
console.log('Prefetch complete');

// ensureQueryData - ensures data is in cache, returns it (fetches if not cached)
const ensuredTodo = await queryClient.ensureQueryData({
  queryKey: todoQueryKey,
  queryFn: fetchTodos,
});
console.log('Ensured:', ensuredTodo);

import { QueryClient } from '@tanstack/react-query';

const queryClient = new QueryClient();

const queryOptions = {
  queryKey: ['todos'],
  queryFn: async () => {
    const response = await fetch('https://jsonplaceholder.typicode.com/todos/1');
    return response.json();
  },
};

// Replaces deprecated fetchQuery()
async function fetchData() {
  const data = await queryClient.query(queryOptions);
  console.log('Fetched:', data);
  return data;
}

// Replaces deprecated ensureQueryData()
async function ensureData() {
  const data = await queryClient.query({
    ...queryOptions,
    staleTime: 'static',
  });
  console.log('Ensured cached:', data);
  return data;
}

// Replaces deprecated prefetchQuery()
async function prefetchData() {
  await queryClient.query({
    ...queryOptions,
    staleTime: 1000 * 60 * 5,
  });
  console.log('Prefetched');
}

// Usage
(async () => {
  await fetchData();
  await ensureData();
  await prefetchData();
})();

import { NextRequest, NextResponse } from 'next/server';
import type { NextMiddleware } from 'next/server';

const middleware: NextMiddleware = (request: NextRequest) => {
  const response = NextResponse.next();
  response.headers.set('X-Custom-Header', 'custom-value');

  if (request.nextUrl.pathname.startsWith('/admin')) {
    const token = request.headers.get('authorization');
    if (!token) {
      return NextResponse.redirect(new URL('/login', request.url));
    }
  }

  return response;
};

export default middleware;

