import { z } from 'zod';

// errorMap: Function that transforms ZodIssue into a custom error message
const customErrorMap = (issue: z.ZodIssue, ctx: z.ErrorMapCtx) => {
  if (issue.code === z.ZodIssueCode.invalid_type) {
    return { message: `Type error: expected ${issue.expected}, got ${issue.received}` };
  }
  return { message: ctx.defaultError };
};

// invalid_type_error: Custom message when a field receives the wrong type
// required_error: Custom message when a required field is missing
const userSchema = z.object({
  name: z.string({
    invalid_type_error: "Name must be a string",
    required_error: "Name is required"
  }),
  email: z.string({
    invalid_type_error: "Email must be a string",
    required_error: "Email is required"
  }),
  age: z.number({
    invalid_type_error: "Age must be a number"
  }).optional()
});

// Demonstrate invalid_type_error
const result1 = userSchema.safeParse({ name: 123, email: "test@example.com" });
if (!result1.success) {
  console.log("Invalid type message:", result1.error.errors[0].message);
  // Output: "Name must be a string"
}

// Demonstrate required_error
const result2 = userSchema.safeParse({ name: "John" });
if (!result2.success) {
  console.log("Required field message:", result2.error.errors[0].message);
  // Output: "Email is required"
}

// Demonstrate errorMap usage
const mappedError = customErrorMap(
  {
    code: z.ZodIssueCode.invalid_type,
    expected: "string",
    received: "number",
    path: ["name"],
    message: "Expected string, received number"
  } as z.ZodIssue,
  { defaultError: "Invalid input" }
);
console.log("ErrorMap result:", mappedError.message);
// Output: "Type error: expected string, got number"

import { z } from 'zod';

// In zod 4.6.7, errorMap, invalid_type_error, required_error, description options
// were removed from object(). Use .superRefine() and field-level validation instead.

const schema = z.object({
  email: z.string().email('Invalid email address'),
  age: z.number().int('Must be an integer').positive('Must be positive'),
  name: z.string().min(1, 'Name is required')
}).superRefine((data, ctx) => {
  // Handles custom validation and error mapping (replaces errorMap, required_error, invalid_type_error)
  if (data.age < 18) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: 'User must be 18 or older',
      path: ['age']
    });
  }
});

// Usage example
const result = schema.safeParse({
  email: 'user@example.com',
  age: 16,
  name: 'John'
});

if (!result.success) {
  result.error.errors.forEach(err => {
    console.log(`${err.path.join('.')}: ${err.message}`);
  });
}

import { streamText } from 'ai';
import { openai } from '@ai-sdk/openai';

async function example() {
  const result = streamText({
    model: openai('gpt-4'),
    prompt: 'Answer questions using available tools',

    // maxTokens: Limits the maximum number of tokens in the response
    maxTokens: 1024,

    // maxSteps: Limits the maximum number of agentic steps (iterations where tools can be called)
    maxSteps: 5,

    // toolCallStreaming: When true, tool calls are streamed immediately as available
    // instead of waiting for the complete response
    toolCallStreaming: true,

    tools: {
      calculator: {
        description: 'Perform mathematical calculations',
        parameters: {
          type: 'object' as const,
          properties: {
            expression: { type: 'string', description: 'Math expression to evaluate' }
          },
          required: ['expression']
        },
        execute: async ({ expression }: { expression: string }) => {
          return (eval(expression) as number).toString();
        }
      }
    }
  });

  // Stream and process events
  for await (const event of result.fullStream) {
    if (event.type === 'text-delta') {
      process.stdout.write(event.delta);
    } else if (event.type === 'tool-call') {
      console.log(`\n[Tool: ${event.toolName}]`);
    }
  }
}

example();

import { streamText, tool } from 'ai';
import { anthropic } from '@ai-sdk/anthropic';

// In ai@7.0.142, maxTokens, maxSteps, and toolCallStreaming were removed from streamText() options
// These configurations are now handled differently:

const result = await streamText({
  model: anthropic('claude-3-5-sonnet-20241022'),
  messages: [{ role: 'user', content: 'What is the weather?' }],
  // maxTokens is no longer an option - handled by model configuration
  // maxSteps is no longer an option - agentic behavior configured elsewhere
  // toolCallStreaming is no longer an option - streaming handled via result.stream
  tools: {
    weather: tool({
      description: 'Get weather',
      // parameters no longer accepted in tool(), use execute function instead
      execute: async ({ location }: { location: string }) => {
        return `Weather in ${location}: Sunny`;
      },
    }),
  },
});

// Stream handling - replaces toolCallStreaming functionality
for await (const chunk of result.stream) {
  if (chunk.type === 'text-delta') {
    process.stdout.write(chunk.delta);
  } else if (chunk.type === 'tool-call') {
    console.log('Tool called:', chunk.toolName);
  }
}

